import Foundation

/// A single motivational quote shown on the Pomodoro break-over screen.
struct MotivationalQuote: Equatable, Identifiable {
    let id: Int
    let text: String
    let author: String
}

/// Offline corpus of inspirational quotes (verbatim text + author), collected
/// once from the Goodreads "inspirational" tag. Quotes are shown in their
/// original language regardless of the app's language setting.
/// See docs/superpowers/specs/2026-06-22-break-over-quote-design.md.
enum MotivationalQuotes {
    static let all: [MotivationalQuote] = [
