    /// Returns a random quote, never the one whose id equals `excluding`
    /// (so the same line never repeats back-to-back when the list has >1 item).
    static func random(excluding: Int? = nil) -> MotivationalQuote {
        let pool = all.count > 1 ? all.filter { $0.id != excluding } : all
        return pool.randomElement() ?? all[0]
    }
}
